class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        ci = {}
        l=0
        ml = 0
        for r in range(len(s)):
            if s[r] in ci and ci[s[r]]>=l:
                l = ci[s[r]]+1
            ci[s[r]] =r
            ml = max(ml,r-l+1)
        return ml

class Solution:
   # median of two sorted arrays
    def findMedianSortedArrays(self,nums1, nums2):
        A, B = nums1, nums2
        total = len(A) + len(B)
        half = total // 2

        if len(A) > len(B):
            A, B = B, A

        l, r = 0, len(A) - 1
        while True:
            i = (l + r) // 2  # A pointer
            j = half - i - 2  # B pointer

            Aleft = A[i] if i >= 0 else float("-infinity")
            Aright = A[i + 1] if (i + 1) < len(A) else float("infinity")
            Bleft = B[j] if j >= 0 else float("-infinity")
            Bright = B[j + 1] if (j + 1) < len(B) else float("infinity")

            # partition is correct
            if Aleft <= Bright and Bleft <= Aright:
                # odd
                if total % 2:
                    return min(Aright, Bright)
                # even
                return (max(Aleft, Bleft) + min(Aright, Bright)) / 2
            elif Aleft > Bright:
                r = i - 1
            else:
                l = i + 1

class Solution:
    def longestPalindrome(self, s: str) -> str:
        def expand(i, j):
            left = i
            right = j

            while left >= 0 and right < len(s) and s[left] == s[right]:
                left -= 1
                right += 1

            return right - left - 1

        ans = [0, 0]

        for i in range(len(s)):
            odd_length = expand(i, i)
            if odd_length > ans[1] - ans[0] + 1:
                dist = odd_length // 2
                ans = [i - dist, i + dist]

            even_length = expand(i, i + 1)
            if even_length > ans[1] - ans[0] + 1:
                dist = (even_length // 2) - 1
                ans = [i - dist, i + 1 + dist]

        i, j = ans
        return s[i : j + 1]

class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1 or numRows >= len(s):
            return s

        idx, d = 0, 1
        rows = [[] for _ in range(numRows)]

        for char in s:
            rows[idx].append(char)
            if idx == 0:
                d = 1
            elif idx == numRows - 1:
                d = -1
            idx += d

        for i in range(numRows):
            rows[i] = ''.join(rows[i])

        return ''.join(rows)

class Solution(object):
    def reverse(self, x):
        """
        Reverse the digits of an integer.

        :type x: int
        :rtype: int
        """
        # Check if the number is non-negative
        if x >= 0:
            # Convert the number to a string, reverse the string, and convert it back to an integer
            reversed_num = int(str(x)[::-1])
            # Check if the reversed number is within the 32-bit signed integer range
            if reversed_num < 2147483647:
                return reversed_num
            else:
                # Return 0 if the reversed number is not within the range
                return 0
        else:
            # Convert the negative number to a positive, reverse it, and add a negative sign
            reversed_num = int("-" + str(abs(x))[::-1])
            # Check if the reversed number is within the 32-bit signed integer range
            if reversed_num > -2147483648:
                return reversed_num
            else:
                # Return 0 if the reversed number is not within the range
                return 0

class Solution:
    def myAtoi(self, s: str) -> int:
        i=0
        sign=+1
        result=''
        if s=='+1':
            return 1
        while i< len(s) and s[i]==' ':
            i += 1
        if i < len(s) and s[i]=='-':
            sign= -1
            i+=1 
        elif i< len(s) and s[i]=='+' :
            sign = +1
            i+=1    
        while i< len(s) and s[i].isdigit():
            result = result+s[i]
            i=i+1
        # what the next lines does: Convert the string res into an integer,
        # multiply by sign and clamp the result: max(-2e31, min(2e31-1, result)).    

        return max( -2**31, min( sign * int(result or 0), 2**31 - 1 ) )

