class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        # nums[:] = sorted(set(nums))
        # return len(nums)
        if not nums:
            return 0 
        write_index = 1
        for i in range(1, len(nums)):
            if nums[i] != nums[i-1]:
                nums[write_index] = nums[i]
                write_index+=1
