class Solution:
    def solveSudoku(self, board: List[List[str]]) -> bool:
        # Helper functions
        def isValid(row: int, col: int, c: str) -> bool:
            return c not in rows[row] and c not in cols[col] and c not in boxes[3 * (row // 3) + (col // 3)]

        def placeNumber(row: int, col: int, c: str):
            board[row][col] = c
            rows[row].add(c)
            cols[col].add(c)
            boxes[3 * (row // 3) + (col // 3)].add(c)

        def removeNumber(row: int, col: int, c: str):
            board[row][col] = "."
            rows[row].remove(c)
            cols[col].remove(c)
            boxes[3 * (row // 3) + (col // 3)].remove(c)

        def backtrack(index: int) -> bool:
            if index == len(empty_cells):
                return True

            row, col = empty_cells[index]
            for c in "123456789":
                if isValid(row, col, c):
                    placeNumber(row, col, c)
                    if backtrack(index + 1):
                        return True
                    removeNumber(row, col, c)
            return False

        # Precompute sets for rows, columns, and boxes
        rows = [set() for _ in range(9)]
        cols = [set() for _ in range(9)]
        boxes = [set() for _ in range(9)]

        empty_cells = []

        for r in range(9):
            for c in range(9):
                if board[r][c] == ".":
                    empty_cells.append((r, c))
                else:
                    placeNumber(r, c, board[r][c])

        # Sort empty cells by the number of possible values (constraint propagation)
        empty_cells.sort(key=lambda cell: sum(1 for c in "123456789" if isValid(cell[0], cell[1], c)))

        backtrack(0)

class Solution:
    def countAndSay(self, n: int) -> str:
        return ''.join([str(c) for c in self.count(0,n-1,[1])])[::-1]

    def count(self,cn,n,seq):
        if n==cn:
            return seq
        new_seq = self.compress(seq)
        return self.count(cn+1,n,new_seq)

    def compress(self,seq):
        res=[]
        cnt=[seq[0],0]
        for i in seq:
            if i==cnt[0]:
                cnt[1]+=1
            else:
                res.extend(cnt)
                cnt=[i,1]
        res.extend(cnt)
        return res

class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        result = []

        def backtrack(start, target, combination):
            # Base case: when the target becomes 0, record the combination
            if target == 0:
                result.append(list(combination))
                return
            # Explore candidates starting from 'start'
            for i in range(start, len(candidates)):
                if candidates[i] > target:
                    continue
                # Choose the current number
                combination.append(candidates[i])
                # Recursive call with the same number (unlimited usage allowed)
                backtrack(i, target - candidates[i], combination)
                # Undo the choice (backtrack)
                combination.pop()

        backtrack(0, target, [])
        return result

class Solution:
    def combinationSum2(
        self, candidates: List[int], target: int
    ) -> List[List[int]]:
        def backtrack(answer, temp_list, candidates, total_left, index):
            if total_left < 0:
                return
            elif total_left == 0:
                answer.append(temp_list.copy())
            else:
                for i in range(index, len(candidates)):
                    if i > index and candidates[i] == candidates[i - 1]:
                        continue
                    if total_left < candidates[i]:
                        break
                    temp_list.append(candidates[i])
                    backtrack(
                        answer,
                        temp_list,
                        candidates,
                        total_left - candidates[i],
                        i + 1,
                    )
                    temp_list.pop()

        result = []
        candidates.sort()
        backtrack(result, [], candidates, target, 0)
        return result

class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            while 1 <= nums[i] <= n and nums[nums[i]-1] != nums[i]:
                # FIX: Use nums[i] (not nums[i-1]) to get the correct target index for swapping
                nums[nums[i]-1], nums[i] = nums[i], nums[nums[i]-1]
        for i in range(n):
            if nums[i] != i+1:
                return i+1
        return n+1

