class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if t == "":
            return ""
        countT, window = {}, {}
        for char in t:
            countT[char] = countT.get(char, 0) + 1
        have, need = 0, len(countT)
        res, resLen = [-1, -1], float("infinity")
        left = 0
        for right in range(len(s)):
            char = s[right]
            window[char] = window.get(char, 0) + 1
            if char in countT and window[char] == countT[char]:
                have += 1
            while have == need:
                if (right - left + 1) < resLen:
                    res = [left, right]
                    resLen = right - left + 1
                window[s[left]] -= 1
                if s[left] in countT and window[s[left]] < countT[s[left]]:
                    have -= 1
                left += 1   
        return "" if res[0] == -1 else s[res[0]:res[1] + 1]

class Solution:
    def exist(self, board, word):
        row,cols = len(board), len(board[0])
        def dfs(r,c,idx):
            if idx == len(word):
                return True
            if r<0 or c<0 or r>=row or c>=cols or board[r][c]!=word[idx]:
                return False
            visited = board[r][c]
            board[r][c] = '#'
            found = (
                dfs(r+1,c,idx+1) or
                dfs(r-1,c,idx+1) or
                dfs(r,c+1,idx+1) or
                dfs(r,c-1,idx+1)
            )
            board[r][c] = visited
            return found
        for r in range(row):
            for c in range(cols):
                if dfs(r,c,0):
                    return True
        return False

