class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []

        res = []
        q = deque([root])

        while q:
            qLen = len(q)
            # The last node in this level is the rightmost
            for i in range(qLen):
                node = q.popleft()
                # Only add non-null children to avoid queue bloat
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
                # Track the last node in current level
                if i == qLen - 1:
                    res.append(node.val)

        return res

class Solution:
    #use a dfs helper function to traverse in all 4 directions
    # usually working on the input data is frowned upon, we need to confirm with the interviewer that we can work on input 
    # or make the copy of the input and work on that
    # also work on the union find algo
    def numIslands(self, grid):
        if not grid:
            return 0
        rows,cols = len(grid),len(grid[0])
        numIslands = 0
        def dfs(r,c):
            if r<0 or r>=rows or c<0 or c>=cols or grid[r][c]=='0':
                return 
            grid[r][c] = '0'
            dfs(r+1,c)
            dfs(r-1,c)
            dfs(r,c+1)
            dfs(r,c-1)
        for r in range(rows):
            for c in range(cols):
                if grid[r][c]=='1':
                    numIslands+=1
                    dfs(r,c)
        return numIslands

