class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 0 or nums is None:
            return 0

        if len(nums) == 1:
            return nums[0]

        return max(self.rob_simple(nums[:-1]), self.rob_simple(nums[1:]))

    def rob_simple(self, nums: List[int]) -> int:
        t1 = 0
        t2 = 0
        for current in nums:
            temp = t1
            t1 = max(current + t2, t1)
            t2 = temp

        return t1

function createMinHeap() {
    const heap = [];

    function size() {
        return heap.length;
    }

    function peek() {
        return heap[0];
    }

    function push(val) {
        heap.push(val);
        bubbleUp();
    }

    function pop() {
        if (size() === 1) return heap.pop();

        const min = heap[0];
        heap[0] = heap.pop();
        bubbleDown();
        return min;
    }

    function bubbleUp() {
        let index = size() - 1;
        while (index > 0) {
            let parent = Math.floor((index - 1) / 2);
            if (heap[parent] <= heap[index]) break;
            [heap[parent], heap[index]] = [heap[index], heap[parent]];
            index = parent;
        }
    }

    function bubbleDown() {
        let index = 0;
        const length = size();

        while (true) {
            let left = index * 2 + 1;
            let right = index * 2 + 2;
            let smallest = index;

            if (left < length && heap[left] < heap[smallest]) {
                smallest = left;
            }
            if (right < length && heap[right] < heap[smallest]) {
                smallest = right;
            }
            if (smallest === index) break;

            [heap[index], heap[smallest]] = [heap[smallest], heap[index]];
            index = smallest;
        }
    }

    return { push, pop, peek, size };
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var findKthLargest = function(nums, k) {
    const minHeap = createMinHeap();

    for (let num of nums) {
        minHeap.push(num);
        if (minHeap.size() > k) {
            minHeap.pop();
        }
    }

    return minHeap.peek();
};

