class UnionFind:
    def __init__(self,n):
        self.parent = list(range(n))
    def find(self,x):
        if self.parent[x]!=x:
            self.parent[x]=self.find(self.parent[x])
        return self.parent[x]    

    def union(self,x,y):
        px = self.find(x)
        py = self.find(y)
        if px == py:
            return False # cycle
        self.parent[py] = px
        return True            


class Solution:
    def findRedundantConnection(self, edges):
        n = len(edges)
        uf = UnionFind(n+1)
        for u,v in edges:
