        self.ans = 0
        def dfs(node):
            if not node:
                return 0
            ll = dfs(node.left)
            rl = dfs(node.right)
            lp=rp=0
            if node.left and node.left.val == node.val:
                lp=ll+1
            if node.right and node.right.val == node.val:
                rp=rl+1
            self.ans = max(self.ans,lp+rp)
            return max(lp,rp)
        dfs(root)
        return self.ans

