            if time > dist[node]:
                continue
            for nei,w in graph[node]:
                nt = time+w
                if nt < dist[nei]:
                    dist[nei]= nt
                    heapq.heappush(heap,(nt,nei))
        ans = max(dist.values())
        return ans if ans<float('inf') else -1

