class Solution:
    def snakesAndLadders(self, board):
        n = len(board)

        def get_pos(s):
            s -= 1
            r = n - 1 - (s // n)
            c = s % n
            if ((n - 1 - r) % 2) == 1:
                c = n - 1 - c
            return r, c

        queue = deque([(1, 0)])  # (square, moves)
        visited = set([1])

        while queue:
            square, moves = queue.popleft()

            for i in range(1, 7):
                next_square = square + i
                if next_square > n * n:
                    continue

                r, c = get_pos(next_square)
                if board[r][c] != -1:
                    next_square = board[r][c]

                if next_square == n * n:
                    return moves + 1

                if next_square not in visited:
                    visited.add(next_square)
                    queue.append((next_square, moves + 1))

        return -1

