class Solution:
    def shortestBridge(self, grid):
        rows, cols = len(grid), len(grid[0])
        directions = [(1,0), (-1,0), (0,1), (0,-1)]
        queue = deque()

        # Phase 1: DFS to find and mark the first island
        def dfs(r, c):
            if (
                r < 0 or r >= rows or
                c < 0 or c >= cols or
                grid[r][c] != 1
            ):
                return
            grid[r][c] = -1  # mark visited
            queue.append((r, c))
            for dr, dc in directions:
                dfs(r + dr, c + dc)

        found = False
        for r in range(rows):
            if found:
                break
            for c in range(cols):
                if grid[r][c] == 1:
                    dfs(r, c)
                    found = True
                    break

        # Phase 2: BFS to expand island
        steps = 0
        while queue:
            for _ in range(len(queue)):
                r, c = queue.popleft()
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == 1:
                            return steps
                        if grid[nr][nc] == 0:
                            grid[nr][nc] = -1
                            queue.append((nr, nc))
            steps += 1

