class Solution:
    def smallestSubsequence(self, s: str) -> str:
        stack = []
        for i in range(len(s)):
            if s[i] in stack:
                continue
            if not stack or (ord(s[i]) > ord(stack[-1])):
                stack.append(s[i])
            elif ord(s[i]) < ord(stack[-1]):
                if stack[-1] not in s[i:]: 
                    stack.append(s[i])
                else:
                    while stack and ord(s[i]) <= ord(stack[-1]):
                        if stack[-1] not in s[i:]:
                            break
                        stack.pop()
                    stack.append(s[i])

        return "".join(stack)

class Solution:
    def duplicateZeros(self, arr: List[int]) -> None:
        """
        Do not return anything, modify arr in-place instead.
        """
        n = len(arr)
        zeros = 0

        # Count how many zeros would be duplicated
        for i in range(n):
            if arr[i] == 0:
                zeros += 1


        i = n - 1
        j = n + zeros - 1  

        while i < j:
            if j < n:
                arr[j] = arr[i]

            if arr[i] == 0:
                j -= 1
                if j < n:
                    arr[j] = 0

            i -= 1
            j -= 1

