class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        stack = []
        remove = set()

        # First pass: handle ')'
        for i, ch in enumerate(s):
            if ch == '(':
                stack.append(i)
            elif ch == ')':
                if stack:
                    stack.pop()
                else:
                    remove.add(i)

        # Remaining '(' are unmatched
        while stack:
            remove.add(stack.pop())

        # Build result
        result = []
        for i, ch in enumerate(s):
            if i not in remove:
                result.append(ch)

        return "".join(result)

