        row_count = [0] * m  # Count of servers in each row
        col_count = [0] * n  # Count of servers in each column

        # Count servers in each row and column
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    row_count[i] += 1
                    col_count[j] += 1

        # Count servers that can communicate
        count = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1 and (row_count[i] > 1 or col_count[j] > 1):
                    count += 1

        return count



class TrieNode:
    def __init__(self):
        self.children = {}
        self.suggestions = []

class Trie:
    def __init__(self):
        self.root = TrieNode()

    # Insert a product into the Trie
    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            # Maintain a list of lexicographically smallest suggestions
            if len(node.suggestions) < 3:
                node.suggestions.append(word)

    # Search the Trie for a given prefix and collect up to 3 suggestions
    def search(self, prefix):
        node = self.root
        result = []
        for char in prefix:
            if char in node.children:
                node = node.children[char]
                result.append(node.suggestions)
            else:
                # If the prefix is not found, return empty lists for the rest of the characters
                while len(result) < len(prefix):
                    result.append([])
                break
        return result

