class Solution:
    def differByOne(self, d):
        mod = 1000000007
        n = len(d)
        m = len(d[0])
        hash_values = [0] * n

        for i in range(n):
            for j in range(m):
                hash_values[i] = (26 * hash_values[i] + (ord(d[i][j]) - ord('a'))) % mod

        mult = 1
        for j in range(m - 1, -1, -1):
            hash_map = {}
            for i in range(n):
                h = (hash_values[i] - (mult * (ord(d[i][j]) - ord('a'))) ) % mod
                if h in hash_map:
                    for pi in hash_map[h]:
                        if d[i][:j] == d[pi][:j] and d[i][j+1:] == d[pi][j+1:]:
                            return True
                if h not in hash_map:
                    hash_map[h] = []
                hash_map[h].append(i)
            mult = (26 * mult) % mod

        return False

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n= len(arr)
        left = 0
        while left< n-1 and arr[left]<=arr[left+1]:
            left+=1
        if left ==n-1:
            return 0
        right = n-1
        while right>0 and arr[right-1]<=arr[right]:
            right-=1
        min_len = min(n-left-1,right)
        i,j = 0,right
        while i<=left and j<n:
            if arr[i]<=arr[j]:
                min_len = min(min_len,j-i-1)
                i+=1
            else:
                j+=1
        return min_len

