class Solution:

    def nearestExit(self,maze, entrance):
        m, n = len(maze), len(maze[0])
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        queue = deque([(entrance[0], entrance[1], 0)])  # (row, col, steps)
        maze[entrance[0]][entrance[1]] = '+'  # Mark entrance as visited

        while queue:
            row, col, steps = queue.popleft()

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc

                if 0 <= new_row < m and 0 <= new_col < n and maze[new_row][new_col] == '.':
                    # If it's an exit (border cell and not the entrance)
                    if new_row == 0 or new_row == m-1 or new_col == 0 or new_col == n-1:
                        return steps + 1

                    # Mark as visited and continue BFS
                    maze[new_row][new_col] = '+'
                    queue.append((new_row, new_col, steps + 1))

        return -1  # No exit found

