class Solution:
    def kthSmallestProduct(self, nums1, nums2, k):
        # Helper function to count how many products <= x
        def check(x):
            total = 0
            for n1 in nums1:
                if n1 > 0:
                    # For positive n1, count nums2[j] <= x // n1
                    total += bisect(nums2, x // n1)
                if n1 < 0:
                    # For negative n1, count nums2[j] >= ceil(x / n1)
                    total += len(nums2) - bisect_left(nums2, ceil(x / n1))
                if n1 == 0 and x >= 0:
                    # For zero n1, product is 0, which is <= x if x >= 0
                    total += len(nums2)
            return total

        # Binary search for the k-th smallest product
        beg, end = -10**10 - 1, 10**10 + 1

        while beg + 1 < end:
            mid = (beg + end) // 2
            if check(mid) >= k:
                # If there are at least k products <= mid, search left
                end = mid
            else:
                # Otherwise, search right
                beg = mid

        # The answer is the smallest value with at least k products <= it
        return beg + 1

class Bank:
    def __init__(self, balance: List[int]):
        self.balance = balance

    def transfer(self, account1: int, account2: int, money: int) -> bool:
        if (
            account1 > len(self.balance)
            or account2 > len(self.balance)
            or self.balance[account1 - 1] < money
        ):
            return False
        self.balance[account1 - 1] -= money
        self.balance[account2 - 1] += money
        return True

    def deposit(self, account: int, money: int) -> bool:
        if account > len(self.balance):
            return False
        self.balance[account - 1] += money
        return True

    def withdraw(self, account: int, money: int) -> bool:
        if account > len(self.balance) or self.balance[account - 1] < money:
            return False
        self.balance[account - 1] -= money
        return True

class Solution:
    def kMirror(self, k: int, n: int) -> int:
        def isPalindrome(x: int) -> bool:
            digit = list()
            while x:
                digit.append(x % k)
                x //= k
            return digit == digit[::-1]

        left, cnt, ans = 1, 0, 0
        while cnt < n:
            right = left * 10
            # op = 0 indicates enumerating odd-length palindromes
            # op = 1 indicates enumerating even-length palindromes
            for op in [0, 1]:
                # enumerate i'
                for i in range(left, right):
                    if cnt == n:
                        break

                    combined = i
                    x = i // 10 if op == 0 else i
                    while x:
                        combined = combined * 10 + x % 10
                        x //= 10
                    if isPalindrome(combined):
                        cnt += 1
                        ans += combined
            left = right

        return ans

