class Solution:
    def findSubtreeSizes(self, parent: List[int], s: str) -> List[int]:

        n = len(parent)

        tree = defaultdict(list)
        for child in range(1, n):
            tree[parent[child]].append(child)

        new_parent = parent[:]

        closest_ancestor = defaultdict(list)

        def dfs(node):
            char = s[node]
            if closest_ancestor[char]:
                new_parent[node] = closest_ancestor[char][-1]

            closest_ancestor[char].append(node)

            for child in tree[node]:
                dfs(child)

            closest_ancestor[char].pop()

        dfs(0)

        new_tree = defaultdict(list)
        for child in range(1, n):
            new_tree[new_parent[child]].append(child)

        subtree_size = [0] * n

        def calculate_size(node):
            size = 1 
            for child in new_tree[node]:
                size += calculate_size(child)
            subtree_size[node] = size
            return size

        calculate_size(0)

        return subtree_size

class Solution:
    def possibleStringCount(self, word: str, k: int) -> int:
        mod = 10**9 + 7
        n, cnt = len(word), 1
        freq = list()

        for i in range(1, n):
            if word[i] == word[i - 1]:
                cnt += 1
            else:
                freq.append(cnt)
                cnt = 1
        freq.append(cnt)

        ans = 1
        for o in freq:
            ans = ans * o % mod

        if len(freq) >= k:
            return ans

        f, g = [1] + [0] * (k - 1), [1] * k
        for i in range(len(freq)):
            f_new = [0] * k
            for j in range(1, k):
                f_new[j] = g[j - 1]
                if j - freq[i] - 1 >= 0:
                    f_new[j] = (f_new[j] - g[j - freq[i] - 1]) % mod
            g_new = [f_new[0]] + [0] * (k - 1)
            for j in range(1, k):
                g_new[j] = (g_new[j - 1] + f_new[j]) % mod
            f, g = f_new, g_new
        return (ans - g[k - 1]) % mod

class Solution:
    def countValidSelections(self,nums):
        n = len(nums)

        def simulate(start_pos, direction, curr_nums):
            nums_copy = curr_nums.copy()
            curr = start_pos

            while 0 <= curr < n:
                if nums_copy[curr] == 0:
                    curr = curr + (1 if direction else -1)
                else:
                    nums_copy[curr] -= 1
                    direction = not direction
                    curr = curr + (1 if direction else -1)

            return all(num == 0 for num in nums_copy)

        valid_count = 0

        for pos in range(n):
            if nums[pos] == 0:
                if simulate(pos, True, nums):
                    valid_count += 1

                if simulate(pos, False, nums):
                    valid_count += 1

        return valid_count

